import {rubberHoseControls,applyRubberHoseControl} from './rubberhose-rig.js';
import {movePivot} from '../scene/pivot.js';
import {editMesh} from '../scene/mesh-edit.js';
import {editorControls,editorAction,editorInput} from './editor.js';
import {showLayerMenu} from './layer-menu.js';
import {objectColourPatch,normalColour} from './object-colour.js';
import {escape} from '../renderer/svg.js';
import {evaluated,setProperty,enableTrack,activeTracks} from '../animation/evaluate.js';
import {find,animatable,clone,isLocked,locate} from '../document/model.js';
import {localBounds,world,point,inverse,multiply,identity} from '../scene/matrix.js';

export const propertyTabs=[['transform','Transform'],['style','Style'],['shape','Shape'],['animate','Animate']];
export function editorSectionTab(title){if(title==='Object selection'||title==='Align selection')return 'transform';if(title.startsWith('Line style')||title==='Mesh shading')return 'style';return 'shape';}
export function propertyKeyState(n,prop,time){const track=activeTracks(n,time)[prop]||[];return {enabled:track.length>0,current:track.some(k=>Math.abs(k.time-time)<.00001)};}
export function propertyKeyButton(n,prop,label,time){const state=propertyKeyState(n,prop,time);return `<button type="button" class="key-button ${state.enabled?'enabled':''} ${state.current?'at-key':''}" data-key="${prop}" data-key-label="${escape(label)}" aria-pressed="${state.enabled}" aria-label="${escape(label)} · ${state.current?'keyframe here':state.enabled?'animation enabled':'animation off'} · add keyframe at ${time.toFixed(2)} seconds" title="${state.enabled?'Add keyframe at current time':'Enable animation from its starting value'}">${state.current?'●':state.enabled?'◇':'+'}</button>`;}
export function displayedSize(n,time,key){const v=evaluated(n,time);if(n.type==='group')return localBounds(n,time)[key]*Math.abs(v[key==='width'?'scaleX':'scaleY']);if(['path','freehand'].includes(n.type)&&!n.rawPath)return localBounds(n,time)[key];return v[key];}
function editorSections(a,n){const box=document.createElement('div');box.innerHTML=editorControls(a,n);const parts={transform:'',style:'',shape:''};for(const section of box.children){const old=section.querySelector('.prop-title'),title=old?.textContent||'';if(old){const heading=document.createElement('h3');heading.className='prop-title';heading.textContent=title;old.replaceWith(heading);}if(n.type==='image'&&editorSectionTab(title)==='shape')continue;parts[editorSectionTab(title)]+=section.outerHTML;}return parts;}
const section=(title,body)=>`<section class="prop-section"><h3 class="prop-title">${title}</h3>${body}</section>`;
export function propertyPanels(a,n,extra={transform:'',style:'',shape:''}){
 const v=evaluated(n,a.time),field=(key,label,options={})=>{const type=options.type||'number',value=['width','height'].includes(key)?displayedSize(n,a.time,key):v[key],shown=type==='color'&&value==='none'?(a.drawColor||'#a8adb5'):value;return `<div class="prop-field ${animatable.includes(key)?'keyable':''} ${options.full?'full-field':''}"><label>${label}<input data-prop="${key}" type="${type}" ${type==='number'?`step="${options.step||1}"`:''} value="${escape(shown)}" ${options.min!==undefined?`min="${options.min}"`:''} ${options.max!==undefined?`max="${options.max}"`:''}></label>${animatable.includes(key)?propertyKeyButton(n,key,label,a.time):''}</div>`;};
 const transform=section('Position & size',`<div class="prop-grid">${field('x','Position X')}${field('y','Position Y')}${field('width','Width',{min:1})}${field('height','Height',{min:1})}${field('rotation','Rotation °')}${field('scaleX','Scale X',{step:.05})}${field('scaleY','Scale Y',{step:.05})}</div>${n.type==='group'?'<p class="subtle">Width and height scale the whole group. Children keep their own geometry.</p>':''}`)+section('Pivot & resizing',`<div class="prop-grid">${field('anchorX','Pivot X')}${field('anchorY','Pivot Y')}</div><button id="center-pivot">Centre pivot</button><label class="properties-check"><input type="checkbox" id="constrain" ${a.constrain?'checked':''}> Keep proportions</label><label class="properties-check"><input type="checkbox" id="from-center" ${a.fromCenter?'checked':''}> Resize from centre</label>`)+extra.transform;
 const opacity=section('Opacity',field('opacity','Opacity',{step:.05,min:0,max:1}));
 let style=opacity+(n.type==='group'?section('Group appearance','<p class="subtle">Select a child to edit its fill, stroke or shading.</p><button data-edit="contents">Select contents</button>'):n.type==='image'?section('Image appearance','<p class="subtle">Opacity fades this image.</p>'):section('Fill & stroke',`<div class="prop-grid">${field('fill','Fill colour',{type:'color'})}${field('stroke','Stroke colour',{type:'color'})}</div><label class="properties-check"><input type="checkbox" data-no-fill ${v.fill==='none'?'checked':''}> No fill</label><div class="stroke-width-control">${field('strokeWidth','Stroke width (px)',{min:0,step:.5})}<input type="range" data-prop="strokeWidth" data-width-slider aria-label="Stroke width slider in pixels" min="0" max="${Math.max(100,Math.ceil(v.strokeWidth))}" step=".5" value="${v.strokeWidth}"></div><p class="subtle" data-stroke-status>${v.strokeWidth>0?'Stroke is visible.':'Stroke width is 0: increase it to show the outline.'}</p>`)+extra.style)+section('Effects',`<div class="editor-buttons">${!['text','group','image'].includes(n.type)?`<button data-edit="texture">${n.texture?'Edit texture':'Image texture'}</button>${n.texture?'<button data-edit="texture-remove">Remove texture</button>':''}`:''}<button data-properties-layer>${n.reference?'Reference options':n.type==='group'?'Group options':'Drop shadow'}</button><button data-motion-blur aria-haspopup="dialog">Motion blur…</button></div>`);

 const text=n.type==='text'?section('Text',`<div class="prop-grid">${field('text','Content',{type:'text',full:true})}${field('fontSize','Font size',{min:1})}<label>Alignment<select data-prop="align">${['left','center','right'].map(x=>`<option ${n.align===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="full-field">Font<select data-prop="font">${['sans-serif','serif','monospace','Arial','Georgia'].map(x=>`<option ${n.font===x?'selected':''}>${x}</option>`).join('')}</select></label></div>`):'';
 const path=['path','freehand'].includes(n.type)&&!n.rawPath&&!n.rubberhoseRig?.enabled?section('Path outline',`<button id="close-path">${n.closed||n.nodes.some(p=>p.close)?'Open path':'Close path'}</button><p class="subtle">Select a square point on the canvas to edit its corner or curve handles.</p>`):'';
 const shape=rubberHoseControls(n,a.time)+text+path+extra.shape||(n.type==='group'?section('Group contents','<button data-edit="contents">Select contents</button><p class="subtle">Direct select edits a shape inside the group.</p>'):section('Shape geometry','<button data-edit="direct">Edit points</button><p class="subtle">Choose Direct select to edit this shape on the canvas.</p>'));
 const labels={x:'Position X',y:'Position Y',rotation:'Rotation',scaleX:'Scale X',scaleY:'Scale Y',opacity:'Opacity',fill:'Fill',stroke:'Stroke',strokeWidth:'Stroke width',nodes:'Path points',mesh:'Mesh shading',shadowX:'Shadow X',shadowY:'Shadow Y',shadowBlur:'Shadow blur',shadowOpacity:'Shadow opacity',shadowColor:'Shadow colour'},props=['x','y','rotation','scaleX','scaleY','opacity'];if(!['group','image'].includes(n.type))props.push('fill','stroke','strokeWidth');if(['path','freehand'].includes(n.type)&&!n.rawPath)props.push('nodes');if(n.mesh)props.push('mesh');if(n.shadowEnabled)props.push('shadowX','shadowY','shadowBlur','shadowOpacity','shadowColor');
 const animate=section('Animation at '+a.time.toFixed(2)+' seconds',`<p class="subtle">Auto Key records edits at the playhead. With it off, use the round key buttons to enable each property.</p><div class="property-track-list">${props.map(prop=>{const state=propertyKeyState(n,prop,a.time);return `<div class="property-track-item"><span><strong>${labels[prop]}</strong><small>${state.current?'Keyframe here':state.enabled?'Animation enabled':'Animation off'}</small></span>${propertyKeyButton(n,prop,labels[prop],a.time)}</div>`;}).join('')}</div>`)+section('Reset animation','<button id="remove-animation">Remove animation tracks</button><p class="subtle">Keeps this frame’s appearance. Undo restores the animation.</p>');
 return {transform,style,shape,animate};
}

export class Properties{
 constructor(app,container){this.app=app;this.el=container;this.tab='transform';try{const saved=localStorage.getItem('poppy-properties-tab');if(propertyTabs.some(([id])=>id===saved))this.tab=saved;}catch{}container.addEventListener('input',e=>this.input(e));container.addEventListener('change',e=>{if(this.pending)this.flush();else this.change(e);});container.addEventListener('click',e=>{const tab=e.target.closest('[data-properties-tab]')?.dataset.propertiesTab;if(tab)return this.selectTab(tab);if(e.target.closest('[data-motion-blur]'))return app.safe(()=>app.showMotionBlur?.(app.selected[0]));if(e.target.closest('[data-properties-layer]'))return app.safe(()=>showLayerMenu(app));const action=e.target.closest('[data-edit]')?.dataset.edit;if(action)return app.safe(()=>editorAction(app,action));this.key(e);});container.addEventListener('keydown',e=>this.tabKeyboard(e));}
 selectTab(tab){if(!propertyTabs.some(([id])=>id===tab))return;this.flush();this.tab=tab;try{localStorage.setItem('poppy-properties-tab',tab);}catch{}this.render(true);const panel=this.el.closest('.inspector');if(panel)panel.scrollTop=0;}
 tabKeyboard(e){const tab=e.target.closest('[data-properties-tab]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();let index=propertyTabs.findIndex(([id])=>id===tab.dataset.propertiesTab);index=e.key==='Home'?0:e.key==='End'?propertyTabs.length-1:(index+(e.key==='ArrowLeft'?-1:1)+propertyTabs.length)%propertyTabs.length;this.selectTab(propertyTabs[index][0]);this.el.querySelector(`[data-properties-tab="${this.tab}"]`)?.focus();}
 render(force=false){const a=this.app,n=find(a.doc,a.selected[0]),active=document.activeElement;if(!force&&this.currentId===n?.id&&this.el.contains(active)&&active?.matches('[data-prop],[data-mesh-prop],[data-geometry],[data-node-prop]'))return;this.currentId=n?.id;if(!n){this.el.innerHTML='<div class="empty-properties"><strong>Choose an object</strong><p>Tap artwork or a layer name to open its properties.</p><p>Transform moves it. Style changes its colour and line. Shape edits its points. Animate controls keyframes.</p></div>';return;}if(n.reference){this.el.innerHTML=section('Reference · '+escape(n.name),'<p class="subtle">Locked frames for tracing. Draw on a new layer above.</p><label>Reference opacity<input data-reference-opacity type="range" min=".05" max="1" step=".05" value="'+n.opacity+'"></label><label class="properties-check"><input data-reference-export type="checkbox" '+(n.exportIncluded?'checked':'')+'> Include reference in exports</label>');this.el.querySelector('[data-reference-opacity]').onchange=e=>a.mutate('Reference opacity',()=>n.opacity=Number(e.target.value));this.el.querySelector('[data-reference-export]').onchange=e=>a.mutate('Reference export visibility',()=>n.exportIncluded=e.target.checked);return;}
  if(this.currentTool!==a.tool){if(['direct','mesh','text'].includes(a.tool))this.tab='shape';this.currentTool=a.tool;}
  const panels=propertyPanels(a,n,editorSections(a,n));this.el.innerHTML=`<input class="property-name" data-prop="name" value="${escape(n.name)}" aria-label="Layer name"><div class="properties-tabs" role="tablist" aria-label="Object properties">${propertyTabs.map(([id,label])=>`<button id="properties-tab-${id}" role="tab" data-properties-tab="${id}" aria-controls="properties-panel-${id}" aria-selected="${this.tab===id}" tabindex="${this.tab===id?0:-1}" class="${this.tab===id?'active':''}">${label}</button>`).join('')}</div>${propertyTabs.map(([id])=>`<section id="properties-panel-${id}" class="properties-tabpanel" role="tabpanel" aria-labelledby="properties-tab-${id}" ${this.tab!==id?'hidden':''}>${panels[id]}</section>`).join('')}`;
  if(isLocked(a.doc,n.id))this.el.querySelectorAll('input,select,button:not([data-properties-tab])').forEach(el=>el.disabled=true);
  this.el.querySelector('#center-pivot').onclick=()=>a.mutate('Centre pivot',()=>{const b=localBounds(n,a.time);movePivot(a.doc,n,{x:b.x+b.width/2,y:b.y+b.height/2},a.time);});
  this.el.querySelector('#constrain').onchange=e=>a.constrain=e.target.checked;this.el.querySelector('#from-center').onchange=e=>a.fromCenter=e.target.checked;this.el.querySelector('#close-path')?.addEventListener('click',()=>editorAction(a,'toggle-close'));this.el.querySelector('#remove-animation').onclick=()=>a.mutate('Remove animation',()=>{Object.assign(n,evaluated(n,a.time),{tracks:{}});delete n.blocks;delete n.blockCuts;});
 }
 syncKeyStates(n){if(!this.el?.querySelectorAll)return;for(const button of this.el.querySelectorAll('[data-key]')){const prop=button.dataset.key,state=propertyKeyState(n,prop,this.app.time),label=button.dataset.keyLabel||prop;button.classList.toggle('enabled',state.enabled);button.classList.toggle('at-key',state.current);button.textContent=state.current?'●':state.enabled?'◇':'+';button.setAttribute('aria-pressed',state.enabled);button.setAttribute('aria-label',label+' · '+(state.current?'keyframe here':state.enabled?'animation enabled':'animation off')+' · add keyframe at '+this.app.time.toFixed(2)+' seconds');const status=button.closest('.property-track-item')?.querySelector('small');if(status)status.textContent=state.current?'Keyframe here':state.enabled?'Animation enabled':'Animation off';}}
 flush(){clearTimeout(this.inputTimer);if(this.pending){this.pending=false;this.app.history.commit('Edit property');}}
 syncStrokeWidth(value){if(!this.el?.querySelectorAll)return;for(const input of this.el.querySelectorAll('[data-prop="strokeWidth"]')){if(input.type==='range'&&value>Number(input.max))input.max=Math.ceil(value);input.value=value;}const status=this.el.querySelector('[data-stroke-status]');if(status)status.textContent=value>0?'Stroke is visible.':'Stroke width is 0: increase it to show the outline.';}
 applyProperty(n,key,value){const a=this.app;if(["fill","stroke"].includes(key)&&normalColour(value)){for(const [prop,colourValue] of Object.entries(objectColourPatch(n,key,value,a.time)))setProperty(n,prop,colourValue,a.time);a.rememberColor(value);return;}if(['anchorX','anchorY'].includes(key)){const v=evaluated(n,a.time);movePivot(a.doc,n,{x:key==='anchorX'?value:v.anchorX,y:key==='anchorY'?value:v.anchorY},a.time);return;}if(['width','height'].includes(key)&&n.type==='group'){const axis=key==='width'?'scaleX':'scaleY',b=localBounds(n,a.time),current=evaluated(n,a.time)[axis];if(b[key]>0)setProperty(n,axis,(current<0?-1:1)*value/b[key],a.time);return;}if(['width','height'].includes(key)&&n.mesh){const axis=key==='width'?'x':'y',f=value/Math.max(.0001,['path','freehand'].includes(n.type)?localBounds(n,a.time)[key]:n[key]);editMesh(n,a.time,m=>{const b=m.bounds;for(const p of m.points)p[axis]=b[axis]+(p[axis]-b[axis])*f;b[key]*=f;return m;});}if(['width','height'].includes(key)&&['path','freehand'].includes(n.type)&&!n.rawPath){const b=localBounds(n,a.time),axis=key==='width'?'x':'y',f=value/Math.max(.0001,b[key]),nodes=clone(evaluated(n,a.time).nodes);for(const p of nodes)for(const q of [p,p.in,p.out].filter(Boolean))q[axis]=b[axis]+(q[axis]-b[axis])*f;setProperty(n,'nodes',nodes,a.time);}if(key==='strokeWidth'&&value>0&&evaluated(n,a.time).stroke==='none')setProperty(n,'stroke',a.drawColor||'#a8adb5',a.time);setProperty(n,key,value,a.time);if(['fill','stroke'].includes(key))a.rememberColor(value);}
 input(e){if(editorInput(this,e))return;const key=e.target.dataset.prop;if(!key)return;if(e.target.tagName==='SELECT'){this.flush();return;}if(e.target.type==='checkbox')return;const a=this.app,n=find(a.doc,a.selected[0]);if(!n||isLocked(a.doc,n.id))return;const numeric=['number','range'].includes(e.target.type);let value=numeric?Number(e.target.value):e.target.value;if(numeric&&(e.target.value===''||!Number.isFinite(value)))return;value=normalizedValue(key,value);a.pause();a.history.begin();this.applyProperty(n,key,value);if(key==='strokeWidth')this.syncStrokeWidth(value);this.syncKeyStates(n);this.pending=true;a.renderStage();clearTimeout(this.inputTimer);this.inputTimer=setTimeout(()=>this.flush(),500);}
 change(e){const a=this.app,n=find(a.doc,a.selected[0]),key=e.target.dataset.prop;if(!n||isLocked(a.doc,n.id))return;if(e.target.dataset.hose){const input=e.target,value=input.type==='checkbox'?input.checked:Number(input.value);if(input.type!=='checkbox'&&(input.value===''||!Number.isFinite(value)))return;return a.safe(()=>applyRubberHoseControl(a,n,input.dataset.hose,value));}if(e.target.hasAttribute('data-no-fill'))return a.mutate('Fill',()=>setProperty(n,'fill',e.target.checked?'none':a.drawColor,a.time));if(!key)return;const numeric=['number','range'].includes(e.target.type);let value=numeric?Number(e.target.value):e.target.value;if(numeric&&(e.target.value===''||!Number.isFinite(value)))return;value=normalizedValue(key,value);a.mutate('Change '+key,()=>this.applyProperty(n,key,value));if(key==='strokeWidth')this.syncStrokeWidth(value);}
 key(e){const prop=e.target.closest('[data-key]')?.dataset.key;if(!prop)return;const a=this.app,n=find(a.doc,a.selected[0]);if(n&&!isLocked(a.doc,n.id))a.mutate('Add keyframe',()=>enableTrack(n,prop,a.time,a.ease));}
}
function normalizedValue(key,value){if(key==='opacity')return Math.max(0,Math.min(1,value));if(['width','height','fontSize'].includes(key))return Math.max(1,value);if(key==='strokeWidth')return Math.max(0,value);return value;}
